import fs from "node:fs";
import path from "node:path";

const root =
  process.cwd();

const marker =
  "AE_UI_POLISH_PACK_11_COMPACT_START";

const styleRelative =
  "artifacts/animated-effects/src/style.css";

const styleFile =
  path.join(
    root,
    styleRelative,
  );

function fail(
  message,
) {
  console.error(
    "\nERROR:",
    message,
  );
  process.exit(
    1,
  );
}

if (
  !fs.existsSync(
    path.join(
      root,
      "pnpm-workspace.yaml",
    ),
  )
) {
  fail(
    "Uruchom instalator z katalogu głównego aplikacja-turnieje-live.",
  );
}

if (
  !fs.existsSync(
    styleFile,
  )
) {
  fail(
    "Brak " +
    styleRelative,
  );
}

const current =
  fs.readFileSync(
    styleFile,
    "utf8",
  );

if (
  !current.includes(
    "AE_UI_POLISH_PACK_10_START",
  )
) {
  fail(
    "Pack 11 wymaga wcześniej zainstalowanego UI Polish Pack 10.",
  );
}

if (
  current.includes(
    marker,
  )
) {
  console.log(
    "UI Polish Pack 11 jest już zainstalowany.",
  );
  process.exit(
    0,
  );
}

const stamp =
  new Date()
    .toISOString()
    .replace(
      /[:.]/g,
      "-",
    )
    .replace(
      "T",
      "_",
    )
    .replace(
      "Z",
      "",
    );

const backup =
  path.join(
    root,
    ".ae-pack-backup",
    `pack-11-ui-compact-${stamp}`,
    styleRelative,
  );

fs.mkdirSync(
  path.dirname(
    backup,
  ),
  {
    recursive:
      true,
  },
);

fs.copyFileSync(
  styleFile,
  backup,
);

const cssPatch =
  Buffer.from(
    "",
    "hex",
  ).toString(
    "utf8",
  );

fs.writeFileSync(
  styleFile,
  current.trimEnd() +
  "\n\n" +
  cssPatch.trim() +
  "\n",
  "utf8",
);

const rollbackPath =
  path.join(
    root,
    "ae-ui-polish-pack-11-compact-rollback.mjs",
  );

const rollback =
`import fs from "node:fs";
import path from "node:path";

const root =
  process.cwd();

const styleFile =
  path.join(
    root,
    ${JSON.stringify(
      styleRelative,
    )},
  );

const backup =
  ${JSON.stringify(
    backup,
  )};

if (
  !fs.existsSync(
    backup,
  )
) {
  console.error(
    "Brak backupu:",
    backup,
  );
  process.exit(
    1,
  );
}

fs.copyFileSync(
  backup,
  styleFile,
);

console.log(
  "UI Polish Pack 11 cofnięty.",
);
`;

fs.writeFileSync(
  rollbackPath,
  rollback,
  "utf8",
);

console.log("");
console.log("================================================");
console.log(" Animated Effects UI Polish Pack 11 INSTALLED");
console.log("================================================");
console.log("");
console.log("Zakres: tylko UI/UX.");
console.log("");
console.log("Zmiany:");
console.log(" - nieaktywne karty efektów są niższe");
console.log(" - + wraca do prawej strony karty, zamiast zabierać cały drugi rząd");
console.log(" - aktywne karty nadal mają osobny rząd - / licznik / +");
console.log(" - filtry Widok + Sortuj są w jednym rzędzie");
console.log(" - mniej pionowego miejsca traconego na filtry i hint");
console.log(" - inspector jest ok. 20-25% bardziej zwarty");
console.log(" - większy mikro-tekst i lepszy kontrast");
console.log(" - Charakter efektu pozostaje wysoko, ale zajmuje mniej miejsca");
console.log(" - Randomness / nagłówki mają poprawione odstępy");
console.log(" - header i preview są trochę bardziej kompaktowe");
console.log(" - mocniej rozróżnione stany hover / preview / aktywny");
console.log("");
console.log(
  "Backup:",
  path.relative(
    root,
    backup,
  ),
);
console.log(
  "Rollback: .\\ae-ui-polish-pack-11-compact-rollback.mjs",
);
console.log("");
console.log("Teraz uruchom:");
console.log("  pnpm --filter animated-effects run typecheck");
console.log("  pnpm --filter animated-effects run build");
